import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '급여 담당자';
const ROLE_ADMIN = '시스템 관리자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const REPORT_TYPES = [
  'WITHHOLDING_STATUS',
  'TUITION_REPAYMENT',
  'LOCAL_INCOME_TAX',
  'RESIDENT_TAX_EMPLOYER',
  'PAYMENT_STATEMENT',
  'SUBMISSION_SUMMARY',
];
const STATUSES = ['미확정', '확정'];
const MONTH_PATTERN = /^\d{6}$/;

const COLUMNS =
  'withholding_report_id AS "withholdingReportId", ' +
  'attribution_month AS "attributionMonth", ' +
  'payment_month AS "paymentMonth", ' +
  'report_division AS "reportDivision", ' +
  'report_type AS "reportType", ' +
  'status AS "status", ' +
  'report_data AS "reportData"';

function invalidInput(message: string): ApiError {
  return new ApiError(422, 'INVALID_WITHHOLDING_INPUT', message);
}

function notFound(): ApiError {
  return new ApiError(404, 'WITHHOLDING_REPORT_NOT_FOUND', '신고서를 찾을 수 없습니다.');
}

function optionalText(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string') {
    throw invalidInput('입력 형식이 올바르지 않습니다.');
  }
  return value;
}

function reportIdOf(req: Request): number {
  const id = Number(req.params['withholdingReportId']);
  if (!Number.isInteger(id) || id <= 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '신고서 ID 형식이 올바르지 않습니다.');
  }
  return id;
}

@Controller('api/v1')
export class FnSfr02301Controller {
  @Post('/withholding-reports')
  @HttpCode(200)
  async createWithholdingReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const paydayId = Number(data['paydayId']);
    if (data['paydayId'] === null || data['paydayId'] === '' || !Number.isInteger(paydayId) || paydayId <= 0) {
      throw invalidInput('급여 지급일을 선택해 주세요.');
    }
    const attributionMonth = data['attributionMonth'];
    if (typeof attributionMonth !== 'string' || !MONTH_PATTERN.test(attributionMonth)) {
      throw invalidInput('귀속연월은 YYYYMM 형식이어야 합니다.');
    }
    const paymentMonth = optionalText(data['paymentMonth']);
    if (paymentMonth !== null && !MONTH_PATTERN.test(paymentMonth)) {
      throw invalidInput('지급연월은 YYYYMM 형식이어야 합니다.');
    }
    const reportDivision = data['reportDivision'];
    if (typeof reportDivision !== 'string' || reportDivision.trim() === '' || reportDivision.length > 30) {
      throw invalidInput('신고구분을 30자 이내로 입력해 주세요.');
    }
    const reportType = data['reportType'];
    if (typeof reportType !== 'string' || !REPORT_TYPES.includes(reportType)) {
      throw invalidInput('신고 유형이 올바르지 않습니다.');
    }
    const reportData = optionalText(data['reportData']);

    return transaction(async (db) => {
      const paydays = await db.query(
        'SELECT payday_id FROM payday WHERE payday_id = CAST(:paydayId AS bigint)',
        { paydayId },
      );
      if (paydays.length === 0) {
        throw new ApiError(404, 'PAYROLL_DATA_NOT_FOUND', '집계 대상 급여 데이터가 없습니다.');
      }
      const dup = await db.query(
        'SELECT withholding_report_id FROM withholding_report ' +
          'WHERE payday_id = CAST(:paydayId AS bigint) AND attribution_month = :attributionMonth ' +
          'AND report_division = :reportDivision AND report_type = :reportType',
        { paydayId, attributionMonth, reportDivision, reportType },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'INVALID_STATE', '같은 신고서가 이미 생성되어 있습니다.');
      }
      // 가정: 신고서 최초 상태는 미확정
      const rows = await db.query(
        'INSERT INTO withholding_report ' +
          '(payday_id, attribution_month, payment_month, report_division, report_type, status, report_data, created_at, updated_at) ' +
          "VALUES (CAST(:paydayId AS bigint), :attributionMonth, :paymentMonth, :reportDivision, :reportType, '미확정', :reportData, now(), now()) " +
          'RETURNING withholding_report_id AS "withholdingReportId", status AS "status", report_data AS "reportData"',
        { paydayId, attributionMonth, paymentMonth, reportDivision, reportType, reportData },
      );
      return rows[0];
    });
  }

  @Get('/withholding-reports')
  async listWithholdingReports(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE, ROLE_ADMIN);
    const query = checks.queryOf(req.query);
    const attributionMonth = optionalQuery(query['attributionMonth']);
    const reportType = optionalQuery(query['reportType']);
    const status = optionalQuery(query['status']);
    if (reportType !== null && !REPORT_TYPES.includes(reportType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고 유형이 올바르지 않습니다.');
    }
    if (status !== null && !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '확정 여부가 올바르지 않습니다.');
    }
    const page = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const size = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    const where =
      'WHERE (CAST(:attributionMonth AS text) IS NULL OR attribution_month = CAST(:attributionMonth AS text)) ' +
      'AND (CAST(:reportType AS text) IS NULL OR report_type = CAST(:reportType AS text)) ' +
      'AND (CAST(:status AS text) IS NULL OR status = CAST(:status AS text))';

    return transaction(async (db) => {
      const filter = { attributionMonth, reportType, status };
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM withholding_report ' + where,
        filter,
      );
      const items = await db.query(
        'SELECT ' + COLUMNS + ' FROM withholding_report ' + where +
          ' ORDER BY withholding_report_id DESC LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        { ...filter, limit, offset: page * limit },
      );
      return { items, page, size: limit, total: Number(counts[0].total) };
    });
  }

  @Patch('/withholding-reports/:withholdingReportId')
  async updateWithholdingReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = reportIdOf(req);
    const data = checks.inputOf(req.body);
    const reportData = data['reportData'];
    if (typeof reportData !== 'string' || reportData.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고 자료를 입력해 주세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM withholding_report WHERE withholding_report_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw notFound();
      }
      if (rows[0].status !== '미확정') {
        throw new ApiError(409, 'WITHHOLDING_REPORT_CONFIRMED', '확정된 신고서는 취소 절차 없이 수정할 수 없습니다.');
      }
      await db.execute(
        'UPDATE withholding_report SET report_data = :reportData, updated_at = now() ' +
          'WHERE withholding_report_id = CAST(:id AS bigint)',
        { id, reportData },
      );
      return { withholdingReportId: id };
    });
  }

  @Post('/withholding-reports/:withholdingReportId/confirm')
  @HttpCode(200)
  async confirmWithholdingReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = reportIdOf(req);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM withholding_report WHERE withholding_report_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw notFound();
      }
      if (rows[0].status !== '미확정') {
        throw new ApiError(409, 'WITHHOLDING_REPORT_CONFIRMED', '이미 확정된 신고서입니다.');
      }
      const updated = await db.query(
        "UPDATE withholding_report SET status = '확정', confirmed_at = now(), updated_at = now() " +
          'WHERE withholding_report_id = CAST(:id AS bigint) ' +
          'RETURNING status AS "status", confirmed_at AS "confirmedAt"',
        { id },
      );
      return updated[0];
    });
  }

  @Get('/withholding-reports/:withholdingReportId/e-filing-file')
  async downloadWithholdingEFilingFile(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = reportIdOf(req);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status", report_data AS "reportData", report_type AS "reportType" ' +
          'FROM withholding_report WHERE withholding_report_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw notFound();
      }
      if (rows[0].status !== '확정') {
        throw new ApiError(409, 'WITHHOLDING_REPORT_NOT_CONFIRMED', '확정되지 않은 신고서입니다.');
      }
      const reportData = rows[0].reportData;
      if (typeof reportData !== 'string' || reportData.trim() === '') {
        throw new ApiError(422, 'E_FILING_FILE_INVALID', '신고 자료가 비어 있어 전자신고 파일을 만들 수 없습니다.');
      }
      // 가정: 국세청 전자신고 형식 명세가 없어 확정된 신고 자료를 텍스트 파일로 그대로 제공한다.
      return {
        file: {
          fileName: 'withholding-report-' + id + '.txt',
          contentType: 'text/plain; charset=utf-8',
          content: reportData,
        },
      };
    });
  }
}

function optionalQuery(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string') {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 조건 형식이 올바르지 않습니다.');
  }
  return value;
}

