import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;
const TYPE_OPTIONS: [string, string][] = [
  ['WITHHOLDING_STATUS', '원천징수이행상황신고서'],
  ['TUITION_REPAYMENT', '학자금상환금명세서'],
  ['LOCAL_INCOME_TAX', '지방소득세 특별징수'],
  ['RESIDENT_TAX_EMPLOYER', '주민세 종업원분'],
  ['PAYMENT_STATEMENT', '지급명세서'],
  ['SUBMISSION_SUMMARY', '제출집계표'],
];
const STATUS_OPTIONS: [string, string][] = [
  ['미확정', '미확정'],
  ['확정', '확정'],
];
const MONTH_PATTERN = /^\d{6}$/;

type PanelMode = 'detail' | 'create' | 'edit' | 'confirm' | 'file';

function typeName(value: unknown): string {
  const found = TYPE_OPTIONS.find(([code]) => code === value);
  return found ? found[1] : String(value ?? '');
}

export default function FnSfr02301Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>({});
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [panel, setPanel] = useState<{ mode: PanelMode; row?: Row } | null>(null);
  const [form, setForm] = useState<Row>({});

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/withholding-reports', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );

  const rows = data ? data.items : [];
  const pendingCount = rows.filter((r) => r.status === '미확정').length;

  function setField(key: string, value: unknown) {
    setForm((prev) => ({ ...prev, [key]: value }));
  }

  function open(mode: PanelMode, row?: Row) {
    if (mode === 'create') {
      setForm({});
    }
    if (mode === 'edit' && row) {
      setForm({ reportData: row.reportData ?? '' });
    }
    setPanel({ mode, row });
  }

  function close() {
    setPanel(null);
  }

  async function submitCreate() {
    if (!form.paydayId) {
      throw new Error('급여 지급일을 선택해 주세요.');
    }
    if (!MONTH_PATTERN.test(String(form.attributionMonth ?? ''))) {
      throw new Error('귀속연월은 YYYYMM 형식 6자리로 입력해 주세요.');
    }
    if (form.paymentMonth && !MONTH_PATTERN.test(String(form.paymentMonth))) {
      throw new Error('지급연월은 YYYYMM 형식 6자리로 입력해 주세요.');
    }
    if (!String(form.reportDivision ?? '').trim()) {
      throw new Error('신고구분을 입력해 주세요.');
    }
    if (!form.reportType) {
      throw new Error('신고 유형을 선택해 주세요.');
    }
    await call('POST', '/withholding-reports', role, {
      paydayId: form.paydayId,
      attributionMonth: form.attributionMonth,
      paymentMonth: form.paymentMonth || undefined,
      reportDivision: form.reportDivision,
      reportType: form.reportType,
      reportData: form.reportData || undefined,
    });
    notify('신고서를 생성했습니다.');
    close();
    reload();
  }

  async function submitEdit() {
    if (!panel || !panel.row) {
      return;
    }
    if (!String(form.reportData ?? '').trim()) {
      throw new Error('신고 자료를 입력해 주세요.');
    }
    await call('PATCH', '/withholding-reports/' + panel.row.withholdingReportId, role, {
      reportData: form.reportData,
    });
    notify('신고서를 수정했습니다.');
    close();
    reload();
  }

  async function submitConfirm() {
    if (!panel || !panel.row) {
      return;
    }
    await call('POST', '/withholding-reports/' + panel.row.withholdingReportId + '/confirm', role, {});
    notify('신고서를 확정했습니다.');
    close();
    reload();
  }

  async function submitFile() {
    if (!panel || !panel.row) {
      return;
    }
    const result = await call<Row>(
      'GET',
      '/withholding-reports/' + panel.row.withholdingReportId + '/e-filing-file',
      role,
    );
    const file = (result.file ?? {}) as Row;
    const blob = new Blob([String(file.content ?? '')], { type: String(file.contentType ?? 'text/plain') });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = String(file.fileName ?? 'withholding-report.txt');
    link.click();
    URL.revokeObjectURL(url);
    notify('전자신고 파일을 내려받았습니다.');
    close();
  }

  const columns: Column[] = [
    { key: 'withholdingReportId', label: '신고서 ID' },
    { key: 'attributionMonth', label: '귀속연월' },
    { key: 'paymentMonth', label: '지급연월' },
    { key: 'reportDivision', label: '신고구분' },
    { key: 'reportType', label: '신고 유형', render: (r) => typeName(r.reportType) },
    { key: 'status', label: '확정 여부', render: (r) => <Badge value={r.status} /> },
  ];

  const target = panel && panel.row ? panel.row : null;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>신고서 현황</h2>
        <Tiles
          items={[
            ['전체 신고서', data ? data.total : 0],
            ['이 쪽 미확정', pendingCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>원천세 신고서</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied({ ...draft });
          }}
          onReset={() => {
            setDraft({});
            setPage(0);
            setApplied({});
          }}
        >
          <Field label="귀속연월">
            <TextInput
              value={draft.attributionMonth}
              onChange={(v) => setDraft({ ...draft, attributionMonth: v })}
              placeholder="YYYYMM"
            />
          </Field>
          <Field label="신고 유형">
            <Select
              value={draft.reportType}
              onChange={(v) => setDraft({ ...draft, reportType: v })}
              options={TYPE_OPTIONS}
              placeholder="전체"
            />
          </Field>
          <Field label="확정 여부">
            <Select
              value={draft.status}
              onChange={(v) => setDraft({ ...draft, status: v })}
              options={STATUS_OPTIONS}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button className="btn" onClick={() => open('create')}>
            신고서 생성
          </button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable columns={columns} rows={rows} onRowClick={(r) => open('detail', r)} empty="신고서가 없습니다." />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>

      {panel && panel.mode === 'create' ? (
        <Drawer title="신고서 생성" onClose={close}>
          <Form onSubmit={submitCreate} submit="생성">
            <Field label="급여 지급일" required>
              <LookupSelect
                table="payday"
                role={role}
                value={form.paydayId}
                onChange={(v) => setField('paydayId', v)}
              />
            </Field>
            <Field label="귀속연월" required hint="YYYYMM">
              <TextInput value={form.attributionMonth} onChange={(v) => setField('attributionMonth', v)} />
            </Field>
            <Field label="지급연월" hint="YYYYMM">
              <TextInput value={form.paymentMonth} onChange={(v) => setField('paymentMonth', v)} />
            </Field>
            <Field label="신고구분" required>
              <TextInput value={form.reportDivision} onChange={(v) => setField('reportDivision', v)} />
            </Field>
            <Field label="신고 유형" required>
              <Select
                value={form.reportType}
                onChange={(v) => setField('reportType', v)}
                options={TYPE_OPTIONS}
              />
            </Field>
            <Field label="신고 자료" wide>
              <TextInput multiline value={form.reportData} onChange={(v) => setField('reportData', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {panel && panel.mode === 'detail' && target ? (
        <Drawer title="신고서 상세" onClose={close}>
          <Pairs
            items={[
              ['신고서 ID', String(target.withholdingReportId)],
              ['급여 지급일', <RefName table="payday" role={role} value={target.paydayId} />],
              ['귀속연월', String(target.attributionMonth ?? '')],
              ['지급연월', String(target.paymentMonth ?? '')],
              ['신고구분', String(target.reportDivision ?? '')],
              ['신고 유형', typeName(target.reportType)],
              ['확정 여부', <Badge value={target.status} />],
              ['확정 일시', <DateText value={target.confirmedAt} time />],
              ['신고 자료', String(target.reportData ?? '')],
            ]}
          />
          {target.status === '미확정' ? (
            <div>
              <button className="btn" onClick={() => open('edit', target)}>
                수정
              </button>
              <button className="btn" onClick={() => open('confirm', target)}>
                확정
              </button>
            </div>
          ) : null}
          {target.status === '확정' ? (
            <div>
              <button className="btn" onClick={() => open('file', target)}>
                전자신고 파일 내려받기
              </button>
            </div>
          ) : null}
        </Drawer>
      ) : null}

      {panel && panel.mode === 'edit' && target ? (
        <Drawer title="신고서 수정" onClose={close}>
          <Form onSubmit={submitEdit} submit="저장">
            <Field label="신고 자료" required wide>
              <TextInput multiline value={form.reportData} onChange={(v) => setField('reportData', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {panel && panel.mode === 'confirm' && target ? (
        <Drawer title="신고서 확정" onClose={close}>
          <Form
            onSubmit={submitConfirm}
            submit="확정"
            danger
            note="확정한 신고서는 취소 절차 없이 수정할 수 없습니다."
          >
            <Pairs
              items={[
                ['귀속연월', String(target.attributionMonth ?? '')],
                ['신고 유형', typeName(target.reportType)],
              ]}
            />
          </Form>
        </Drawer>
      ) : null}

      {panel && panel.mode === 'file' && target ? (
        <Drawer title="전자신고 파일" onClose={close}>
          <Form
            onSubmit={submitFile}
            submit="파일 내려받기"
            note="내려받은 파일은 국세청에 직접 제출해 주세요. 시스템이 국세청에 전송하지 않습니다."
          >
            <Pairs
              items={[
                ['귀속연월', String(target.attributionMonth ?? '')],
                ['신고 유형', typeName(target.reportType)],
              ]}
            />
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
